import math

f = lambda x, y: math.exp(-(x - 1) ** 2 - (y + 2) ** 2)      # a hill centered at (1, -2)
def grad(f, x, y, h=1e-6):
    return ((f(x + h, y) - f(x - h, y)) / (2 * h), (f(x, y + h) - f(x, y - h)) / (2 * h))

for point in [(0.0, 0.0), (2.0, -3.0), (1.0, -2.0)]:
    gx, gy = grad(f, *point)
    print(point, "gradient", (round(gx, 4), round(gy, 4)))    # points toward the hilltop; zero at the top

import math

def to_polar(x, y):
    return math.hypot(x, y), math.degrees(math.atan2(y, x))

def to_cartesian(r, deg):
    return r * math.cos(math.radians(deg)), r * math.sin(math.radians(deg))

print(to_polar(3, 4))                                       # (5.0, 53.13...)
print([round(v, 4) for v in to_cartesian(5, 53.130102)])    # back to (3, 4)

